/**
 * Which files of the library the SERVER wrote itself (knowledge-library.md K13; amendment P2-12a): History records a change it
 * finds on disk as "edited outside BotBoy" unless this says the server produced it. The analytics set's lessons, its
 * `manifest.json` and the presets the manifest tags `etl-derived` are generated by BotBoy's own writers (lessons ledger, ETL
 * onboarding), so a change found at one of those paths is recorded as generated.
 * The classification is by PATH, not by writer, because the writers call no hook. Two consequences, both stated in the map (K13):
 * a user file the owner drops into `presets/` is not mistaken for generated (the manifest does not tag it), and a hand edit of a
 * generated path is reported as generated too, not as outside, until the next regeneration overwrites it.
 */
import fs from 'node:fs';
import path from 'node:path';

interface ManifestCache { mtimeMs: number; size: number; generated: Set<string> }

export function createGeneratedClassifier(root: () => string | null): (relativePath: string) => 'generated' | 'outside' {
  let cache: { root: string; value: ManifestCache } | null = null;

  function etlDerived(base: string): Set<string> {
    const file = path.join(base, 'analytics', 'manifest.json');
    try {
      const stat = fs.statSync(file);
      if (cache && cache.root === base && cache.value.mtimeMs === stat.mtimeMs && cache.value.size === stat.size) return cache.value.generated;
      const parsed = JSON.parse(fs.readFileSync(file, 'utf8')) as { files?: Array<{ file?: unknown; source?: unknown }> };
      const generated = new Set<string>();
      for (const row of Array.isArray(parsed.files) ? parsed.files : []) {
        if (row && row.source === 'etl-derived' && typeof row.file === 'string') generated.add(`analytics/${row.file.split(path.sep).join('/')}`.toLowerCase());
      }
      cache = { root: base, value: { mtimeMs: stat.mtimeMs, size: stat.size, generated } };
      return generated;
    } catch {
      return new Set();
    }
  }

  return (relativePath: string) => {
    const lower = String(relativePath ?? '').toLowerCase();
    if (lower.startsWith('analytics/lessons/') || lower === 'analytics/manifest.json') return 'generated';
    if (!lower.startsWith('analytics/presets/')) return 'outside';
    const base = root();
    return base && etlDerived(base).has(lower) ? 'generated' : 'outside';
  };
}
